package provider

import (
	"archive/zip"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

func resourceArtifactExtract() *schema.Resource {
	return &schema.Resource{
		Create: resourceArtifactExtractCreate,
		Read:   resourceArtifactExtractRead,
		Delete: resourceArtifactExtractDelete,
		Schema: map[string]*schema.Schema{
			"bucket": {Type: schema.TypeString, Required: true, ForceNew: true},
			"key":    {Type: schema.TypeString, Required: true, ForceNew: true},
			"dest":   {Type: schema.TypeString, Required: true, ForceNew: true},
		},
	}
}

func resourceArtifactExtractCreate(d *schema.ResourceData, meta interface{}) error {
	bucket := d.Get("bucket").(string)
	key := d.Get("key").(string)
	dest := d.Get("dest").(string)

	sess, err := session.NewSession(&aws.Config{Region: aws.String("us-east-1")})
	if err != nil {
		return fmt.Errorf("failed to create session: %w", err)
	}
	svc := s3.New(sess)

	tmpFile, err := os.CreateTemp("", "artifact-*.zip")
	if err != nil {
		return fmt.Errorf("failed to create temp file: %w", err)
	}
	defer os.Remove(tmpFile.Name())
	defer tmpFile.Close()

	resp, err := svc.GetObject(&s3.GetObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
	})
	if err != nil {
		return fmt.Errorf("failed to download s3://%s/%s: %w", bucket, key, err)
	}
	defer resp.Body.Close()

	if _, err := io.Copy(tmpFile, resp.Body); err != nil {
		return fmt.Errorf("failed to write temp file: %w", err)
	}
	tmpFile.Close()

	if err := extractZip(tmpFile.Name(), dest); err != nil {
		return fmt.Errorf("extraction failed: %w", err)
	}

	d.SetId(fmt.Sprintf("%s/%s", bucket, key))
	return nil
}

func extractZip(zipPath, dest string) error {
	r, err := zip.OpenReader(zipPath)
	if err != nil {
		return err
	}
	defer r.Close()

	// Normalize destination path
	dest = filepath.Clean(dest)

	for _, f := range r.File {
		// Basic sanitization: remove leading slashes
		name := strings.TrimLeft(f.Name, "/")

		// NOTE: filepath.Join handles the path construction
		// The joined path is used directly for extraction
		fpath := filepath.Join(dest, name)

		// Check for empty name after trim
		if name == "" {
			continue
		}

		if f.FileInfo().IsDir() {
			os.MkdirAll(fpath, 0755)
			continue
		}

		// Ensure parent directory exists
		if err := os.MkdirAll(filepath.Dir(fpath), 0755); err != nil {
			return err
		}

		outFile, err := os.OpenFile(fpath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, f.Mode())
		if err != nil {
			return err
		}

		rc, err := f.Open()
		if err != nil {
			outFile.Close()
			return err
		}

		_, err = io.Copy(outFile, rc)
		rc.Close()
		outFile.Close()
		if err != nil {
			return err
		}
	}
	return nil
}

func resourceArtifactExtractRead(d *schema.ResourceData, meta interface{}) error {
	return nil
}

func resourceArtifactExtractDelete(d *schema.ResourceData, meta interface{}) error {
	d.SetId("")
	return nil
}
